package com.reverseit.cancore

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.io.ByteArrayOutputStream
import java.util.zip.GZIPInputStream
import kotlin.random.Random

/**
 * Parity test for [SlcanReader] against a Python reference reader.
 *
 * Expectations are pre-generated by `tools/slcan_parity_generate.py` and shipped as a TSV in
 * `src/test/resources/slcan_parity_cases.tsv`, with the VCU captures alongside in
 * `src/test/resources/slcan/`.
 *
 * Regenerate after changing either reader:
 *     py -3.12 tools/slcan_parity_generate.py
 *
 * Parity between two implementations is not proof on its own -- a misreading shared by both
 * would survive it. Two things in here are stronger than parity:
 *
 *  - **The block CRCs are an independent oracle.** They were computed by the firmware over the
 *    bytes it actually wrote, so a reader that tokenizes the stream wrongly cannot make them
 *    verify. `serial-full-slcan.log.gz` is the one capture recorded as having no link damage at
 *    all, and all 1381 of its checked blocks must pass.
 *
 *  - **Chunk invariance.** The same capture fed as one buffer and as randomly-sized chunks must
 *    produce byte-identical results. USB bulk reads land wherever they land, so without this the
 *    first mid-frame split would be discovered on a phone, in a car, against a live stream.
 *
 * The damaged captures matter as much as the clean one: the reader has to detect the corruption
 * that is there, not merely avoid inventing corruption that is not.
 */
class SlcanParityTest {

    private data class Expected(
        val counts: MutableMap<String, Long> = mutableMapOf(),
        val samples: MutableMap<Int, String> = mutableMapOf(),
        var digest: Long = 0L,
        var expectClean: Boolean = false,
    )

    private fun loadExpectations(): Map<String, Expected> {
        val tsv = readResourceText("/slcan_parity_cases.tsv")
        val out = LinkedHashMap<String, Expected>()
        for (raw in tsv.lineSequence()) {
            val line = raw.trimEnd('\r', '\n')
            if (line.isEmpty() || line.startsWith("#")) continue
            val cols = line.split('\t')
            require(cols.size == 3) { "malformed parity TSV line: $line" }
            val (fixture, key, value) = cols
            val exp = out.getOrPut(fixture) { Expected() }
            when {
                key == "digest" -> exp.digest = java.lang.Long.parseUnsignedLong(value, 16)
                key == "expectClean" -> exp.expectClean = value == "1"
                key.startsWith("sample.") -> exp.samples[key.removePrefix("sample.").toInt()] = value
                else -> exp.counts[key] = value.toLong()
            }
        }
        assertTrue("no parity cases loaded", out.isNotEmpty())
        return out
    }

    @Test
    fun parityWithReferenceReader() {
        val expectations = loadExpectations()
        val failures = mutableListOf<String>()

        for ((fixture, exp) in expectations) {
            val data = readFixture(fixture)
            val frames = ArrayList<CanFrame>(exp.counts["frames"]?.toInt() ?: 1024)
            val reader = SlcanReader(busIndex = 0, clock = { 0L }) { frames.add(it) }
            reader.feed(data)

            // A missing expectation is a failure, not a pass -- otherwise a typo'd key in the
            // generator would quietly stop testing whatever it named.
            fun check(what: String, expectedValue: Any?, actual: Any) {
                when {
                    expectedValue == null -> failures += "$fixture: no expectation for $what"
                    expectedValue != actual -> failures += "$fixture: $what expected $expectedValue, got $actual"
                }
            }

            val s = reader.stats
            check("frames", exp.counts["frames"], s.frames)
            check("integrity", exp.counts["integrity"], s.integrity)
            check("csv", exp.counts["csv"], s.csv)
            check("acks", exp.counts["acks"], s.acks)
            check("malformed", exp.counts["malformed"], s.malformed)
            check("oversize", exp.counts["oversize"], s.oversize)
            check("blocksChecked", exp.counts["blocksChecked"], s.blocksChecked)
            check("blocksCrcBad", exp.counts["blocksCrcBad"], s.blocksCrcBad)
            check("blocksCountBad", exp.counts["blocksCountBad"], s.blocksCountBad)
            check("digest", exp.digest, reader.digest)
            check("delivered frame count", exp.counts["frames"], frames.size.toLong())

            // The independent oracle: firmware-computed CRCs over the bytes it wrote.
            if (exp.expectClean) {
                check("blocksCrcBad (declared-clean capture)", 0L, s.blocksCrcBad)
                check("blocksCountBad (declared-clean capture)", 0L, s.blocksCountBad)
            }

            for ((idx, encoded) in exp.samples) {
                if (idx >= frames.size) {
                    failures += "$fixture: sample $idx beyond ${frames.size} frames"
                    continue
                }
                val actual = encodeFrame(frames[idx])
                if (actual != encoded) {
                    failures += "$fixture: frame $idx expected $encoded, got $actual"
                }
            }
        }

        if (failures.isNotEmpty()) {
            fail("SLCAN parity failures (${failures.size}):\n" + failures.joinToString("\n"))
        }
    }

    /**
     * The same stream split any way at all must produce the same frames. This is the property
     * the USB read path depends on and the one the fixtures are chosen to stress:
     * `serial-slcan-realistic.log.gz` begins mid-frame, so a reader that mishandles a partial
     * token fails on the very first byte.
     */
    @Test
    fun chunkInvariance() {
        val failures = mutableListOf<String>()

        for (fixture in loadExpectations().keys) {
            val data = readFixture(fixture)

            val whole = SlcanReader(clock = { 0L }) { }
            whole.feed(data)

            // Several seeds, so this does not pass by a lucky split.
            for (seed in longArrayOf(1L, 7L, 12345L)) {
                val rng = Random(seed)
                val chunked = SlcanReader(clock = { 0L }) { }
                var off = 0
                while (off < data.size) {
                    // 1 byte to 3 KB: spans single-byte dribbles through multi-frame reads,
                    // and crosses the 1260-byte CSV records at every offset.
                    val n = minOf(1 + rng.nextInt(3000), data.size - off)
                    chunked.feed(data, off, n)
                    off += n
                }
                if (chunked.digest != whole.digest) {
                    failures += "$fixture seed=$seed: digest ${chunked.digest} != ${whole.digest}"
                }
                for ((what, a, b) in listOf(
                    Triple("frames", whole.stats.frames, chunked.stats.frames),
                    Triple("integrity", whole.stats.integrity, chunked.stats.integrity),
                    Triple("csv", whole.stats.csv, chunked.stats.csv),
                    Triple("malformed", whole.stats.malformed, chunked.stats.malformed),
                    Triple("acks", whole.stats.acks, chunked.stats.acks),
                    Triple("oversize", whole.stats.oversize, chunked.stats.oversize),
                    Triple("blocksChecked", whole.stats.blocksChecked, chunked.stats.blocksChecked),
                    Triple("blocksCrcBad", whole.stats.blocksCrcBad, chunked.stats.blocksCrcBad),
                    Triple("blocksCountBad", whole.stats.blocksCountBad, chunked.stats.blocksCountBad),
                )) {
                    if (a != b) failures += "$fixture seed=$seed: $what whole=$a chunked=$b"
                }
            }
        }

        if (failures.isNotEmpty()) {
            fail("chunk-invariance failures (${failures.size}):\n" + failures.joinToString("\n"))
        }
    }

    /** Hand-written cases for shapes the captures do not contain. */
    @Test
    fun grammarEdgeCases() {
        fun read(s: String): Pair<List<CanFrame>, SlcanReader.Stats> {
            val out = mutableListOf<CanFrame>()
            val r = SlcanReader(clock = { 0L }) { out.add(it) }
            r.feed(s.toByteArray(Charsets.US_ASCII))
            return out to r.stats
        }

        // Standard and extended, all-zero dlc, lowercase hex.
        val (f1, _) = read("t1230\rT1F0000010\rt7f780102030405060708\r")
        assertEquals(3, f1.size)
        assertEquals(0x123, f1[0].id)
        assertEquals(false, f1[0].isExtended)
        assertEquals(0x1F000001, f1[1].id)
        assertEquals(true, f1[1].isExtended)
        assertEquals(0x7F7, f1[2].id)
        assertEquals(8, f1[2].dlc)
        assertEquals(0x08, f1[2].data[7].toInt())

        // Remote frames carry a dlc but no data.
        val (f2, _) = read("r1234\rR1F0000024\r")
        assertEquals(2, f2.size)
        assertEquals(4, f2[0].dlc)
        assertEquals(true, f2[1].isExtended)

        // dlc claims more data than is present; dlc > 8; non-hex body; truncated id.
        val (f3, s3) = read("t1238AABB\rt1239001122334455667788\rt123201GH\rt12\r")
        assertEquals(0, f3.size)
        assertEquals(4L, s3.malformed)

        // A bare CR is an acknowledgement, not a frame. CRLF is one terminator, so a CSV
        // record must not also produce an empty token behind it.
        val (f4, s4) = read("\rtime,a,b\r\nt1230\r")
        assertEquals(1, f4.size)
        assertEquals(1L, s4.acks)
        assertEquals(1L, s4.csv)

        // An oversized token is discarded whole, and the reader resynchronises at the next
        // terminator rather than emitting the tail as a frame.
        val (f5, s5) = read("t" + "0".repeat(SlcanReader.MAX_TOKEN + 50) + "\rt1230\r")
        assertEquals(1, f5.size)
        assertEquals(1L, s5.oversize)
    }

    private fun encodeFrame(f: CanFrame): String {
        val hex = StringBuilder()
        for (i in 0 until f.dlc) hex.append("%02X".format(f.data[i]))
        return "%08X:%d:%d:%s".format(f.id, if (f.isExtended) 1 else 0, f.dlc, hex)
    }

    private fun readResourceText(path: String): String =
        javaClass.getResourceAsStream(path)?.bufferedReader()?.readText()
            ?: throw IllegalStateException("missing test resource $path")

    private fun readFixture(basename: String): ByteArray {
        val stream = javaClass.getResourceAsStream("/slcan/$basename")
            ?: throw IllegalStateException("missing fixture /slcan/$basename")
        val out = ByteArrayOutputStream()
        GZIPInputStream(stream).use { gz ->
            val buf = ByteArray(1 shl 16)
            while (true) {
                val n = gz.read(buf)
                if (n < 0) break
                out.write(buf, 0, n)
            }
        }
        return out.toByteArray()
    }
}
